{"query":"query getWishlistToast($country: String!, $locale: String) {
  Wishlist {
    wishlistToast {
      offers {
        releaseCycle {
          namespace
          offerId
          currentStatus
          previousStatus
          offer(locale: $locale) {
            productSlug
            urlSlug
            title
            id
            namespace
            offerType
            expiryDate
            status
            isCodeRedemptionOnly
            description
            effectiveDate
            pcReleaseDate
            releaseDate
            prePurchase
            keyImages {
              type
              url
            }
            seller {
              id
              name
            }
            productSlug
            urlSlug
            items {
              id
              namespace
            }
            customAttributes {
              key
              value
            }
            developerDisplayName
            publisherDisplayName
            catalogNs {
              mappings(pageType: "productHome") {
                pageSlug
                pageType
              }
            }
            offerMappings {
              pageSlug
              pageType
            }
            categories {
              path
            }
            tags {
              id
              groupName
              name
            }
            price(country: $country) {
              totalPrice {
                discountPrice
                originalPrice
                voucherDiscount
                discount
                fmtPrice(locale: $locale) {
                  originalPrice
                  discountPrice
                  intermediatePrice
                }
                currencyCode
                currencyInfo {
                  decimals
                  symbol
                }
              }
              lineOffers {
                appliedRules {
                  id
                  endDate
                }
              }
            }
          }
        }
        onSale {
          namespace
          offerId
          promotionRuleId
          saleExpirationDate
          offer(locale: $locale) {
            productSlug
            urlSlug
            title
            id
            namespace
            offerType
            expiryDate
            status
            isCodeRedemptionOnly
            description
            effectiveDate
            pcReleaseDate
            releaseDate
            prePurchase
            keyImages {
              type
              url
            }
            seller {
              id
              name
            }
            productSlug
            urlSlug
            items {
              id
              namespace
            }
            customAttributes {
              key
              value
            }
            developerDisplayName
            publisherDisplayName
            catalogNs {
              mappings(pageType: "productHome") {
                pageSlug
                pageType
              }
            }
            offerMappings {
              pageSlug
              pageType
            }
            categories {
              path
            }
            tags {
              id
              groupName
              name
            }
            price(country: $country) {
              totalPrice {
                discountPrice
                originalPrice
                voucherDiscount
                discount
                fmtPrice(locale: $locale) {
                  originalPrice
                  discountPrice
                  intermediatePrice
                }
                currencyCode
                currencyInfo {
                  decimals
